//! Independent full-position regressions. Expectations are transcribed from godip,
//! never generated by the engine under test; see data/oracle_godip.json provenance.
use std::collections::{BTreeMap, BTreeSet};

use cabal_engine::{
    Position, Rulebook,
    adjudicate::{
        adjustment::resolve_adjustment, movement::resolve_movement, retreat::resolve_retreat,
    },
    geo::{Map, Power, ProvinceId},
    order::{Command, Unit},
    parse::parse,
    state::{Dislodged, GameState, Phase},
};
use serde::Deserialize;

#[derive(Deserialize)]
struct Corpus {
    cases: Vec<Case>,
}
#[derive(Deserialize)]
struct ExpectedDislodgement {
    unit: String,
    attacker_from: String,
    by_convoy: bool,
}
#[derive(Deserialize)]
struct Case {
    name: String,
    source_file: String,
    source_case: String,
    godip_commit: String,
    rule_references: Vec<String>,
    phase: String,
    starting_units: Vec<String>,
    starting_dislodged: Vec<String>,
    starting_owners: BTreeMap<String, String>,
    orders: Vec<String>,
    starting_results: Vec<String>,
    upstream_poststate_dislodged: Vec<String>,
    expected_units: Vec<String>,
    expected_dislodged: Vec<String>,
    expected_dislodgement_details: Vec<ExpectedDislodgement>,
    expected_owners: BTreeMap<String, String>,
}
// Translate only jDip/godip notation; the stored source remains verbatim.
fn notation(text: &str) -> String {
    text.replace('-', " - ")
        .split_whitespace()
        .map(|token| match token.to_ascii_lowercase().as_str() {
            "nrg" => "nwg",
            "mid" => "mao",
            "gol" => "lyo",
            _ => token,
        })
        .collect::<Vec<_>>()
        .join(" ")
}
fn unit(text: &str) -> Unit {
    let p = parse(Map::standard(), &notation(text)).unwrap_or_else(|e| panic!("{text}: {e}"));
    Unit {
        power: p.power.unwrap(),
        kind: p.kind.unwrap(),
        region: p.region.unwrap(),
    }
}
fn units(texts: &[String]) -> Vec<Unit> {
    let mut result: Vec<_> = texts.iter().map(|t| unit(t)).collect();
    result.sort_by_key(|u| u.region);
    result
}
fn owners(texts: &BTreeMap<String, String>) -> BTreeMap<ProvinceId, Power> {
    let map = Map::standard();
    texts
        .iter()
        .map(|(p, n)| (map.find_province(p).unwrap(), map.find_power(n).unwrap()))
        .collect()
}
#[test]
fn oracle_godip_full_post_states() {
    let corpus: Corpus = serde_json::from_str(include_str!("data/oracle_godip.json")).unwrap();
    assert!(corpus.cases.len() >= 20);
    let production = corpus
        .cases
        .iter()
        .filter(|c| c.source_file.starts_with("variants/"))
        .count();
    assert_eq!(production, 18, "all original production cases are required");
    let mut seen = BTreeSet::new();
    for case in corpus.cases {
        assert!(seen.insert(case.name.clone()));
        assert!(!case.source_file.is_empty() && !case.source_case.is_empty());
        assert_eq!(case.godip_commit.len(), 40);
        assert!(!case.rule_references.is_empty());
        let map = Map::standard();
        let position = Position {
            units: units(&case.starting_units),
            owners: owners(&case.starting_owners),
        };
        let parsed: Vec<_> = case
            .orders
            .iter()
            .map(|t| parse(map, &notation(t)).unwrap_or_else(|e| panic!("{}: {t}: {e}", case.name)))
            .collect();
        let (position, mut dislodged) = if case.phase.ends_with("Movement") {
            let orders: Vec<_> = parsed
                .iter()
                .map(|p| p.to_movement(None).unwrap())
                .collect();
            let result = resolve_movement(map, &position, Rulebook::default(), &orders);
            let mut expected: Vec<_> = case
                .expected_dislodgement_details
                .iter()
                .map(|d| Dislodged {
                    unit: unit(&d.unit),
                    attacker_from: map.find_province(&d.attacker_from).unwrap(),
                    by_convoy: d.by_convoy,
                })
                .collect();
            expected.sort_by_key(|d| d.unit.region);
            assert_eq!(
                result.dislodged, expected,
                "{}: exact dislodgement metadata",
                case.name
            );
            let mut state =
                GameState::from_position(Phase::parse("S1901R").unwrap(), result.position.clone());
            state.dislodged = result.dislodged.clone();
            state.standoffs = result.standoffs.clone();
            let upstream = units(&case.upstream_poststate_dislodged);
            let mut boundary = Vec::new();
            for d in &result.dislodged {
                if upstream.contains(&d.unit) {
                    boundary.push(d.unit);
                } else {
                    let options = cabal_engine::legal::legal_retreats(map, &state, d.unit.power);
                    assert_eq!(
                        options[&d.unit.province()].len(),
                        1,
                        "{}: source only removes units with no legal retreat",
                        case.name
                    );
                }
            }
            boundary.sort_by_key(|u| u.region);
            assert_eq!(
                boundary, upstream,
                "{}: exact upstream dislodged boundary",
                case.name
            );
            (
                result.position,
                result.dislodged.iter().map(|d| d.unit).collect::<Vec<_>>(),
            )
        } else if case.phase.ends_with("Retreat") {
            let mut state = GameState::from_position(Phase::parse("S1901R").unwrap(), position);
            state.dislodged = units(&case.starting_dislodged)
                .into_iter()
                .map(|unit| Dislodged {
                    unit,
                    attacker_from: unit.province(),
                    by_convoy: false,
                })
                .collect();
            for prior in &case.starting_results {
                let (verdict, text) = prior.split_once(':').expect("source result prefix");
                let order = parse(map, &notation(text))
                    .unwrap()
                    .to_movement(None)
                    .unwrap();
                if let Command::Move {
                    dest, via_convoy, ..
                } = order.command
                {
                    if verdict == "SUCCESS" {
                        for d in &mut state.dislodged {
                            if d.unit.province() == dest {
                                d.attacker_from = order.unit;
                                d.by_convoy = via_convoy;
                            }
                        }
                    } else if !via_convoy {
                        state.standoffs.insert(dest);
                    }
                }
            }
            let orders: Vec<_> = parsed.iter().map(|p| p.to_retreat(None).unwrap()).collect();
            (resolve_retreat(map, &state, &orders).position, vec![])
        } else {
            assert!(case.phase.ends_with("Adjustment"));
            let orders: Vec<_> = parsed
                .iter()
                .map(|p| p.to_adjustment(None).unwrap())
                .collect();
            (
                resolve_adjustment(map, &position, Rulebook::default(), &orders).position,
                vec![],
            )
        };
        dislodged.sort_by_key(|u| u.region);
        assert_eq!(
            position.units,
            units(&case.expected_units),
            "{}: full units",
            case.name
        );
        assert_eq!(
            dislodged,
            units(&case.expected_dislodged),
            "{}: full dislodged",
            case.name
        );
        assert_eq!(
            position.owners,
            owners(&case.expected_owners),
            "{}: full owners",
            case.name
        );
        println!("PASS {}", case.name);
    }
}
